/* ============================================================
   ARCHIVUS — THE REALMS (v11)
   Every country today, from two independent measurements:
     · Freedom House, Freedom in the World 2026 (0–100)
     · V-Dem v16 (expert-coded indices, 1900–2025)
   plus the archive's own notes on form of government and doctrine.
   Views: map · compass · ledger · drift · usa.   Deep link:
     realms.html#v=map&m=fh&y=2025&c=USA
   Data: src/data/realms.js (generated by tools/build-realms.py),
         realms-notes.js and realms-usa.js (hand-written).
   ============================================================ */
(function () {
  "use strict";
  const K = window.ARCHIVUS_KIT, $ = K.$, esc = K.esc;
  const R = window.ARCHIVUS_REALMS, NT = window.ARCHIVUS_REALMS_NOTES, U = window.ARCHIVUS_REALMS_USA;
  const C = R.countries, BY = {}; C.forEach(c => { BY[c.id] = c; });
  const LAST = R.meta.last, Y0 = R.meta.y0;

  /* V-Dem "Regimes of the World" classes */
  const ROW = [["Closed autocracy", "#8a2f2a", "No multiparty elections for the chief executive or the legislature."],
               ["Electoral autocracy", "#c77c3a", "Multiparty elections are held, but they are not free and fair."],
               ["Electoral democracy", "#5b93b8", "Free and fair multiparty elections; weaker protection of rights and limits on the executive."],
               ["Liberal democracy", "#49c9b8", "Free elections plus courts and a legislature that bind the executive, and protected liberties."]];
  const FHS = { F: ["Free", "#49c9b8"], PF: ["Partly Free", "#c9a227"], NF: ["Not Free", "#a23b33"] };
  /* V-Dem: the character of the ideology a government promotes to justify its rule */
  const IDEO = { S: ["Socialist or communist", "#e5484d"], R: ["Religious", "#4caf7d"], C: ["Conservative or restorative", "#9a7fd1"], N: ["Nationalist", "#d9a441"], P: ["Separatist or autonomist", "#5aa9e6"], w: ["No strong ideological claim", "#3a4258"] };
  const FORMC = { PR: "#5b93b8", SP: "#86b9de", PA: "#49c9b8", CM: "#9a7fd1", EM: "#c58fd6", AM: "#d1589a", OP: "#e5484d", MJ: "#8f9a4c", TH: "#4caf7d", DR: "#8fd6a0", TR: "#8d96af", TE: "#55607a" };
  const SIG = { coup: "A coup attempt in the last ten years", force: "A government ended by force in the last ten years", erosion: "Liberal-democracy index down 0.10 or more in five years",
                violence: "Political violence frequent", polarised: "Society split into hostile camps", military: "The executive rests on the armed forces" };
  const SIGK = Object.keys(SIG);
  const ENDT = { 0: "Military coup", 1: "Coup by another group", 2: "Self-coup", 3: "Assassination", 5: "Lost a civil war", 6: "Lost a war between states", 7: "Foreign intervention", 8: "Popular uprising" };
  const RGS = ["Western Europe & North America", "Eastern Europe & Central Asia", "Latin America & Caribbean", "Middle East & North Africa", "Sub-Saharan Africa", "Asia & Pacific"];
  const RGC = ["#5b93b8", "#9a7fd1", "#4caf7d", "#d9a441", "#e5784d", "#d1589a"];
  const RGSHORT = ["W. Europe & N. America", "E. Europe & C. Asia", "Latin America", "Middle East & N. Africa", "Sub-Saharan Africa", "Asia & Pacific"];
  const FREE = K.ramp(["#5e1f22", "#9c3b2c", "#c9772e", "#d9b23c", "#7cc4a0", "#3fb6c9"]);
  const DRIFT = K.ramp(["#e0482f", "#93483a", "#39415a", "#3a8f8a", "#49c9b8"]);
  const HEAT = K.ramp(["#232a3c", "#6b5326", "#b06a2a", "#e0672f", "#ff3d3d"]);

  const st = { v: "map", c: null, m: "fh", y: LAST, cc: "row", cy: "ldi", rg: null, fs: null, sort: "fh", dir: -1, mv: 5, tk: null,
               ds: "world", us: "now", te: 0, ud: 0, ur: 0 };   /* ds/us: the open section of the Drift and the United States */
  const built = {};
  let map = null, mapTip = null, yc = null, tabs = null;

  const formOf = c => NT.form[c.id];
  const formName = c => { const f = NT.forms[formOf(c)]; return f ? f[0] : "—"; };
  /* the colour key for a government's claimed ideology: the more specific character wins over "nationalist" */
  const ideoKey = c => { if (!c.ideo) return null; if (c.ideo[0] < 2) return "w"; const s = c.ideo[1]; return "SRCNP".split("").find(k => s.indexOf(k) >= 0) || "w"; };
  const ideoWords = c => !c.ideo ? "—" : c.ideo[0] < 2 ? "none strongly" : (c.ideo[1].split("").map(k => IDEO[k][0].split(" ")[0].toLowerCase()).join(" + ") || "unclassified");
  const eco = c => c.own == null || c.prop == null ? null : 0.5 * c.own / 4 + 0.5 * c.prop;   /* 0 state-run … 1 private */
  const ldiAt = (c, y) => !c.hl ? null : y >= LAST ? c.ldi : (c.hl[y - Y0] < 0 ? null : c.hl[y - Y0] / 100);
  const rowAt = (c, y) => !c.hr ? null : y >= LAST ? c.row : (c.hr[y - Y0] === "-" ? null : +c.hr[y - Y0]);
  const delta = (c, k) => k === 1 ? c.d1 : k === 10 ? c.d10 : c.d5;
  const ranked = C.filter(c => c.ldi != null).sort((a, b) => b.ldi - a.ldi);
  const src = k => { const s = U.src[k]; return s ? s[1] : k.indexOf("w:") === 0 ? "https://en.wikipedia.org/wiki/" + k.slice(2) : k; };
  const srcLinks = keys => keys.map(k => K.link(src(k), U.src[k] ? U.src[k][0].split(" — ")[0].replace(/^Wikipedia$/, "Wikipedia: " + U.src[k][0].split(" — ")[1]) : K.host(src(k)))).join("");

  /* ---------------- state ---------------- */
  function sync(skipHash) {
    if (!skipHash) K.hash.write({ v: st.v, s: st.v === "usa" ? st.us : st.v === "drift" ? st.ds : null, c: st.c, m: st.v === "map" && st.m !== "fh" ? st.m : null, y: st.v === "map" && st.y !== LAST ? st.y : null });
    tabs.paint();
    document.body.classList.toggle("doc", st.v === "usa");
    renderSide(); render(st.v);            /* the side panel first: charts are drawn to the width it leaves */
  }
  function go(v) { if (tabs.ids.indexOf(v) < 0) return; st.v = v; if (yc) yc.stop(); sync(); }
  function pick(iso, quiet) {
    st.c = iso && BY[iso] ? iso : null;
    if (st.v === "usa" && st.c) st.v = "map";
    sync();
    if (st.c && st.v === "map" && map && !quiet) map.focus(st.c);
  }
  function render(v) {
    if (v === "map") drawMap(); else if (v === "compass") drawCompass(); else if (v === "ledger") drawLedger();
    else if (v === "drift") drawDrift(); else if (v === "usa") drawUSA();
  }

  /* ---------------- the map ---------------- */
  const MODES = {
    fh: ["Freedom score", "Freedom House, Freedom in the World 2026: political rights and civil liberties, 0–100"],
    ldi: ["Liberal democracy", "V-Dem liberal democracy index, 0–1 — drag the year back to 1900"],
    row: ["Regime type", "V-Dem's four regime classes — drag the year back to 1900"],
    form: ["Form of government", "The constitutional form: how the offices are arranged"],
    ideo: ["Claimed ideology", "V-Dem: the ideology a government promotes to justify its rule (latest coding, 2023)"],
    d5: ["Drift", "Change in the liberal democracy index over the last five years"],
    sig: ["Pressure signals", "How many of six observed strain conditions are present — a count, not a forecast"]
  };
  function colour(c) {
    const m = st.m;
    if (m === "fh") return c.fh ? FREE(c.fh[0] / 100) : null;
    if (m === "ldi") { const v = ldiAt(c, st.y); return v == null ? null : FREE(v); }
    if (m === "row") { const v = rowAt(c, st.y); return v == null ? null : ROW[v][1]; }
    if (m === "form") return FORMC[formOf(c)] || null;
    if (m === "ideo") { const k = ideoKey(c); return k ? IDEO[k][1] : null; }
    if (m === "d5") return c.d5 == null ? null : DRIFT(0.5 + c.d5 / 0.5);
    if (m === "sig") return c.sig ? HEAT(c.sig.length / 6) : null;
    return null;
  }
  function tipFor(iso, name) {
    const c = iso && BY[iso]; if (!c) return "<b>" + esc(name) + "</b><small>not rated</small>";
    const m = st.m; let v = "";
    if (m === "ldi") { const x = ldiAt(c, st.y); v = "liberal democracy " + (x == null ? "— no data" : K.fmt(x)) + " · " + st.y; }
    else if (m === "row") { const x = rowAt(c, st.y); v = (x == null ? "no data" : ROW[x][0]) + " · " + st.y; }
    else if (m === "form") v = formName(c);
    else if (m === "ideo") v = "claims: " + ideoWords(c);
    else if (m === "d5") v = "five-year drift " + K.signed(c.d5);
    else if (m === "sig") v = c.sig ? c.sig.length + " of 6 signals" : "no data";
    return "<b>" + esc(c.n) + "</b>" + (c.fh ? "<small>Freedom House " + c.fh[0] + " · " + FHS[c.fh[1]][0] + "</small>" : "") + (v ? "<small>" + esc(v) + "</small>" : "");
  }
  function legend() {
    const m = st.m, sw = (c, t) => '<span><i style="background:' + c + '"></i>' + esc(t) + "</span>";
    const grad = (fn, a, b, mid) => '<div class="rl-grad" style="background:linear-gradient(90deg,' + [0, .2, .4, .6, .8, 1].map(fn).join(",") + ')"></div><div class="rl-gradk"><span>' + a + "</span>" + (mid ? "<span>" + mid + "</span>" : "") + "<span>" + b + "</span></div>";
    let h = "<b>" + esc(MODES[m][0]) + (m === "ldi" || m === "row" ? " · " + st.y : "") + "</b>";
    if (m === "fh") h += grad(FREE, "0 · not free", "100 · free") + "<small>Freedom in the World 2026 (describes 2025). " + C.filter(c => c.fh && c.fh[1] === "F").length + " countries Free, " + C.filter(c => c.fh && c.fh[1] === "PF").length + " Partly Free, " + C.filter(c => c.fh && c.fh[1] === "NF").length + " Not Free.</small>";
    else if (m === "ldi") h += grad(FREE, "0", "1") + "<small>V-Dem's liberal democracy index: clean elections plus limits on the executive and protected rights. Expert-coded.</small>";
    else if (m === "row") { const n = [0, 0, 0, 0]; C.forEach(c => { const r = rowAt(c, st.y); if (r != null) n[r]++; }); h += ROW.map((r, i) => sw(r[1], r[0] + " " + n[i])).join(""); }
    else if (m === "form") { const n = {}; C.forEach(c => { const f = formOf(c); n[f] = (n[f] || 0) + 1; }); h += Object.keys(NT.forms).filter(k => n[k]).map(k => sw(FORMC[k], NT.forms[k][0] + " " + n[k])).join("") + "<small>How the offices are arranged — not how free the country is. Compiled by the archive.</small>"; }
    else if (m === "ideo") h += "SRCN".split("").concat("w").map(k => sw(IDEO[k][1], IDEO[k][0])).join("") + "<small>What the government itself invokes, as judged by V-Dem's country experts (2023). Where they chose several, the map shows the more specific over \"nationalist\".</small>";
    else if (m === "d5") h += grad(t => DRIFT(t), "−0.25 sliding", "+0.25 rising", "0") + "<small>Liberal democracy index, " + (LAST - 5) + " → " + LAST + ".</small>";
    else if (m === "sig") h += grad(HEAT, "0", "6") + "<small>A count of observed conditions (recent coup attempt, forced change, erosion, violence, polarisation, military executive). It describes strain; it does not predict.</small>";
    $("mp-leg").innerHTML = h;
  }
  function drawMap() {
    if (!built.map) {
      built.map = 1;
      mapTip = K.tip($("mp-tip"), $("mp-wrap"));
      map = K.worldMap($("mp"), { map: R.map, tip: mapTip, tipFor, onPick: iso => pick(iso, true) });
      $("mp-modes").innerHTML = Object.keys(MODES).map(k => '<button class="chipbtn" data-m="' + k + '" title="' + esc(MODES[k][1]) + '">' + MODES[k][0] + "</button>").join("");
      $("mp-modes").addEventListener("click", e => { const b = e.target.closest("button"); if (!b) return; st.m = b.dataset.m; yc.stop(); sync(); });
      yc = K.yearCtl($("mp-year"), { min: Y0, max: LAST, from: Y0, ms: 60, get: () => st.y, set: y => { st.y = y; paintMap(); K.hash.write({ v: st.v, c: st.c, m: st.m, y: st.y !== LAST ? st.y : null }); } });
      $("mp-rank").addEventListener("click", e => { const b = e.target.closest("[data-iso]"); if (b) pick(b.dataset.iso); });
      $("mp-zi").onclick = () => map.zoomBy(1 / 1.6); $("mp-zo").onclick = () => map.zoomBy(1.6); $("mp-zr").onclick = () => map.reset();
    }
    $("mp-modes").querySelectorAll("button").forEach(b => b.classList.toggle("on", b.dataset.m === st.m));
    const timed = st.m === "ldi" || st.m === "row";
    if (!timed) st.y = LAST;
    yc.off(!timed); yc.show();
    paintMap(); map.select(st.c);
  }
  function paintMap() { map.paint(iso => BY[iso] ? colour(BY[iso]) : null); legend(); ribbon(); }
  /* the rank ribbon: every rated country as one bar, in order — the whole distribution at a glance,
     including the small states the map cannot show */
  function ribbon() {
    const m = st.m, cat = m === "row" || m === "form" || m === "ideo", order = m === "form" ? Object.keys(NT.forms) : "wNCRSP".split("");
    const val = c => m === "fh" ? c.fh[0] / 100 : m === "ldi" ? ldiAt(c, st.y) : m === "d5" ? c.d5 : m === "sig" ? c.sig.length + (1 - (c.ldi || 0)) / 10 : m === "row" ? rowAt(c, st.y) + (ldiAt(c, st.y) || 0) / 2 : m === "form" ? order.indexOf(formOf(c)) : order.indexOf(ideoKey(c)) + (c.ideo ? c.ideo[0] / 10 : 0);
    const xs = C.map(c => ({ c, col: colour(c) })).filter(x => x.col).map(x => (x.v = val(x.c), x)).sort((a, b) => a.v - b.v);
    const lo = m === "d5" ? -0.4 : 0, hi = m === "d5" ? 0.4 : m === "sig" ? 6.1 : 1;
    const label = c => m === "fh" ? c.fh[0] + " · " + FHS[c.fh[1]][0] : m === "ldi" ? K.fmt(ldiAt(c, st.y)) : m === "d5" ? K.signed(c.d5) : m === "sig" ? c.sig.length + " of 6" : m === "row" ? ROW[rowAt(c, st.y)][0] : m === "form" ? formName(c) : ideoWords(c);
    $("mp-rank").innerHTML = '<div class="rk-bars">' + xs.map(x => '<i data-iso="' + x.c.id + '"' + (x.c.id === st.c ? ' class="sel"' : "") + ' title="' + esc(x.c.n + " — " + label(x.c)) + '" style="height:' + (cat ? 100 : K.clamp(m === "d5" ? Math.abs(x.v) / 0.4 * 100 : (x.v - lo) / (hi - lo) * 100, 6, 100)).toFixed(0) + "%;background:" + x.col + '"></i>').join("") + "</div>"
      + '<div class="rk-k"><span>◂ ' + (m === "d5" ? "sliding" : cat ? "" : "lowest") + "</span><span>" + xs.length + " countries and territories, one bar each, in order of " + MODES[m][0].toLowerCase() + " — hover for the name, click to open</span><span>" + (m === "d5" ? "rising" : cat ? "" : "highest") + " ▸</span></div>";
  }

  /* ---------------- the compass of nations ---------------- */
  const NCC = { row: "Regime type", fh: "Freedom House status", ideo: "Claimed ideology", form: "Form of government", rg: "Region" };
  function ncColour(c) {
    if (st.cc === "row") return c.row == null ? "#55607a" : ROW[c.row][1];
    if (st.cc === "fh") return c.fh ? FHS[c.fh[1]][1] : "#55607a";
    if (st.cc === "ideo") { const k = ideoKey(c); return k ? IDEO[k][1] : "#55607a"; }
    if (st.cc === "form") return FORMC[formOf(c)] || "#55607a";
    const i = RGS.indexOf(c.rg); return i < 0 ? "#55607a" : RGC[i];
  }
  function drawCompass() {
    if (!built.nc) {
      built.nc = 1;
      $("nc-col").innerHTML = Object.keys(NCC).map(k => '<button class="chipbtn" data-k="' + k + '">' + NCC[k] + "</button>").join("");
      $("nc-col").addEventListener("click", e => { const b = e.target.closest("button"); if (b) { st.cc = b.dataset.k; drawCompass(); } });
      $("nc-y").innerHTML = '<button class="chipbtn" data-k="ldi" title="V-Dem liberal democracy index">Down: V-Dem</button><button class="chipbtn" data-k="fh" title="Freedom House score">Down: Freedom House</button>';
      $("nc-y").addEventListener("click", e => { const b = e.target.closest("button"); if (b) { st.cy = b.dataset.k; drawCompass(); } });
      const tip = K.tip($("nc-tip"), $("nc-wrap")), svg = $("nc");
      svg.addEventListener("pointermove", e => { const c = BY[e.target.dataset && e.target.dataset.iso]; if (!c) return tip.hide(); tip.show("<b>" + esc(c.n) + "</b><small>" + esc(formName(c)) + " · " + (c.row != null ? ROW[c.row][0] : "") + "</small><small>liberal democracy " + K.fmt(c.ldi) + (c.fh ? " · Freedom House " + c.fh[0] : "") + "</small><small>state ownership " + K.fmt(c.own, 1) + " of 4 · property rights " + K.fmt(c.prop) + "</small>", e); });
      svg.addEventListener("pointerleave", () => tip.hide());
      svg.addEventListener("click", e => { const iso = e.target.dataset && e.target.dataset.iso; pick(iso || null); });
      let rt = 0; window.addEventListener("resize", () => { clearTimeout(rt); rt = setTimeout(() => { if (st.v === "compass") drawCompass(); }, 120); });
    }
    $("nc-col").querySelectorAll("button").forEach(b => b.classList.toggle("on", b.dataset.k === st.cc));
    $("nc-y").querySelectorAll("button").forEach(b => b.classList.toggle("on", b.dataset.k === st.cy));
    const svg = $("nc"), box = $("nc-wrap").getBoundingClientRect(), W = Math.max(320, box.width), H = Math.max(300, box.height), small = W < 620;
    const L = small ? 30 : 56, Rm = 16, T = 26, B = small ? 30 : 40, pw = W - L - Rm, ph = H - T - B;
    svg.setAttribute("viewBox", "0 0 " + W + " " + H);
    const yv = c => st.cy === "fh" ? (c.fh ? c.fh[0] / 100 : null) : c.ldi;
    const pts = C.map(c => ({ c, e: eco(c), v: yv(c) })).filter(p => p.e != null && p.v != null);
    /* the economic scores bunch between about 0.25 and 0.95, so the axis is cropped to the data */
    const e0 = 0.05, e1 = 1;
    pts.forEach(p => { p.x = L + (p.e - e0) / (e1 - e0) * pw; p.y = T + p.v * ph; p.r = K.clamp(2.6 + Math.sqrt((p.c.pop || 5e5) / 1e6) * (small ? 0.42 : 0.6), 3, small ? 17 : 25); });
    pts.sort((a, b) => b.r - a.r);
    let h = '<rect class="cp-frame" x="' + L + '" y="' + T + '" width="' + pw + '" height="' + ph + '"/>';
    for (let i = 1; i < 4; i++) h += '<line class="cp-grid" x1="' + L + '" x2="' + (L + pw) + '" y1="' + (T + ph * i / 4) + '" y2="' + (T + ph * i / 4) + '"/><line class="cp-grid" y1="' + T + '" y2="' + (T + ph) + '" x1="' + (L + pw * i / 4) + '" x2="' + (L + pw * i / 4) + '"/>';
    const mx = L + (0.5 - e0) / (e1 - e0) * pw, my = T + ph / 2, qf = small ? 11 : 15;
    h += '<line class="cp-axis" x1="' + mx + '" x2="' + mx + '" y1="' + T + '" y2="' + (T + ph) + '"/><line class="cp-axis" x1="' + L + '" x2="' + (L + pw) + '" y1="' + my + '" y2="' + my + '"/>';
    [["STATE-RUN · UNFREE", L + 10, T + qf + 8, "start", "#e5484d"], ["MARKET · UNFREE", L + pw - 10, T + qf + 8, "end", "#c77c3a"], ["STATE-RUN · FREE", L + 10, T + ph - 12, "start", "#5b93b8"], ["MARKET · FREE", L + pw - 10, T + ph - 12, "end", "#49c9b8"]]
      .forEach(q => { h += '<text class="cp-q" x="' + q[1] + '" y="' + q[2] + '" text-anchor="' + q[3] + '" fill="' + q[4] + '" font-size="' + qf + '">' + q[0] + "</text>"; });
    h += '<text class="cp-ax" x="' + L + '" y="' + (H - 10) + '">◂ state owns the economy</text><text class="cp-ax" x="' + (L + pw) + '" y="' + (H - 10) + '" text-anchor="end">private property secure ▸</text>';
    h += '<text class="cp-ax" x="' + (L + pw / 2) + '" y="' + (T - 9) + '" text-anchor="middle">▴ less free' + (st.cy === "fh" ? " (Freedom House)" : " (V-Dem)") + '</text>';
    if (!small) h += '<text class="cp-ax" transform="translate(16,' + (T + ph) + ') rotate(-90)">freer ▸</text>';
    for (let i = 0; i <= 4; i++) h += '<text class="cp-tick" x="' + (L - 6) + '" y="' + (T + ph * i / 4 + 3) + '" text-anchor="end">' + (st.cy === "fh" ? i * 25 : (i / 4).toFixed(2)) + "</text>";
    pts.forEach(p => { h += '<circle class="nc-d' + (p.c.id === st.c ? " sel" : "") + '" data-iso="' + p.c.id + '" cx="' + p.x.toFixed(1) + '" cy="' + p.y.toFixed(1) + '" r="' + p.r.toFixed(1) + '" fill="' + ncColour(p.c) + '"/>'; });
    /* labels: the most populous countries and the selection, each tried right, left, above, below */
    const boxes = [], fs = small ? 9.5 : 11, hit = b => boxes.some(c => b[0] < c[2] && b[2] > c[0] && b[1] < c[3] && b[3] > c[1]);
    pts.filter(p => p.r > 9).forEach(p => boxes.push([p.x - p.r * .7, p.y - p.r * .7, p.x + p.r * .7, p.y + p.r * .7]));
    const want = pts.slice().sort((a, b) => (b.c.id === st.c) - (a.c.id === st.c) || (b.c.pop || 0) - (a.c.pop || 0)).slice(0, small ? 22 : 60);
    want.forEach(p => {
      const w = p.c.n.length * fs * 0.56 + 4;
      const tries = [[p.x + p.r + 3, p.y + 3.5, "start"], [p.x - p.r - 3, p.y + 3.5, "end"], [p.x, p.y - p.r - 4, "middle"], [p.x, p.y + p.r + fs, "middle"]];
      for (const t of tries) {
        const x0 = t[2] === "start" ? t[0] : t[2] === "end" ? t[0] - w : t[0] - w / 2, b = [x0, t[1] - fs, x0 + w, t[1] + 2];
        if (b[0] < L - 2 || b[2] > W - 2 || b[1] < T || b[3] > T + ph) continue;
        if (hit(b) && p.c.id !== st.c) continue;
        boxes.push(b); h += '<text class="cl' + (p.c.id === st.c ? " sel" : "") + '" x="' + t[0].toFixed(1) + '" y="' + t[1].toFixed(1) + '" text-anchor="' + t[2] + '" font-size="' + fs + '">' + esc(p.c.n) + "</text>"; break;
      }
    });
    svg.innerHTML = h;
  }

  /* ---------------- the ledger ---------------- */
  const COLS = [
    ["n", "Country", c => c.n, ""], ["fh", "Freedom House", c => c.fh ? c.fh[0] : null, ""], ["ldi", "Lib. democracy", c => c.ldi, "num"],
    ["row", "Regime (V-Dem)", c => c.row, ""], ["form", "Form of government", c => formName(c), "hide-s"], ["ideo", "Claims to rule by", c => ideoKey(c) ? ideoWords(c) : null, "hide-s"],
    ["d5", "5-yr drift", c => c.d5, "num"], ["sig", "Signals", c => c.sig ? c.sig.length : null, ""], ["pt", "Coup attempts since 1950", c => c.pt ? c.pt[0] : null, "num hide-s"]
  ];
  function drawLedger() {
    if (!built.lg) {
      built.lg = 1;
      $("lg-rg").innerHTML = RGS.map((r, i) => '<button class="chipbtn" data-k="' + i + '">' + RGSHORT[i] + "</button>").join("");
      $("lg-st").innerHTML = Object.keys(FHS).map(k => '<button class="chipbtn" data-k="' + k + '">' + FHS[k][0] + "</button>").join("");
      $("lg-rg").addEventListener("click", e => { const b = e.target.closest("button"); if (b) { st.rg = st.rg === +b.dataset.k ? null : +b.dataset.k; drawLedger(); } });
      $("lg-st").addEventListener("click", e => { const b = e.target.closest("button"); if (b) { st.fs = st.fs === b.dataset.k ? null : b.dataset.k; drawLedger(); } });
      $("lg").addEventListener("click", e => {
        const th = e.target.closest("th"); if (th) { const k = th.dataset.k; if (st.sort === k) st.dir = -st.dir; else { st.sort = k; st.dir = k === "n" || k === "form" || k === "ideo" ? 1 : -1; } return drawLedger(); }
        const tr = e.target.closest("tr[data-iso]"); if (tr) pick(tr.dataset.iso);
      });
    }
    $("lg-rg").querySelectorAll("button").forEach(b => b.classList.toggle("on", +b.dataset.k === st.rg));
    $("lg-st").querySelectorAll("button").forEach(b => b.classList.toggle("on", b.dataset.k === st.fs));
    const col = COLS.find(c => c[0] === st.sort) || COLS[1], get = col[2];
    const rows = C.filter(c => (st.rg == null || c.rg === RGS[st.rg]) && (!st.fs || (c.fh && c.fh[1] === st.fs)))
      .sort((a, b) => { const x = get(a), y = get(b); if (x == null) return y == null ? 0 : 1; if (y == null) return -1; return (typeof x === "string" ? x.localeCompare(y) : x - y) * st.dir || a.n.localeCompare(b.n); });
    $("lg-n").textContent = rows.length + " of " + C.length + " countries and territories · click a heading to sort, a row to open";
    let h = "<thead><tr>" + COLS.map(c => '<th data-k="' + c[0] + '" class="' + c[3] + (st.sort === c[0] ? " s" + (st.dir > 0 ? " asc" : "") : "") + '">' + c[1] + "</th>").join("") + "</tr></thead><tbody>";
    rows.forEach(c => {
      const ik = ideoKey(c);
      h += '<tr data-iso="' + c.id + '"' + (c.id === st.c ? ' class="sel"' : "") + '><td class="n">' + esc(c.n) + "</td>"
        + "<td>" + (c.fh ? '<span class="bar"><i style="width:' + c.fh[0] + "%;background:" + FREE(c.fh[0] / 100) + '"></i></span><span class="mono">' + c.fh[0] + '</span> <span class="pill ' + c.fh[1] + '">' + FHS[c.fh[1]][0] + "</span>" : "<small>—</small>") + "</td>"
        + '<td class="num">' + K.fmt(c.ldi) + "</td>"
        + "<td>" + (c.row != null ? '<span class="fdot" style="background:' + ROW[c.row][1] + '"></span>' + ROW[c.row][0] : "<small>not covered</small>") + "</td>"
        + '<td class="hide-s"><span class="fdot" style="background:' + (FORMC[formOf(c)] || "#55607a") + '"></span>' + esc(formName(c)) + "</td>"
        + '<td class="hide-s">' + (ik ? '<span class="fdot" style="background:' + IDEO[ik][1] + '"></span>' + esc(ideoWords(c)) : "<small>—</small>") + "</td>"
        + '<td class="num ' + (c.d5 > 0.02 ? "up" : c.d5 < -0.02 ? "dn" : "") + '">' + K.signed(c.d5) + "</td>"
        + "<td>" + (c.sig ? '<span class="sigs" title="' + esc(c.sig.map(s => SIG[s]).join(" · ") || "none") + '">' + SIGK.map(s => '<i class="' + (c.sig.indexOf(s) >= 0 ? "on" : "") + '"></i>').join("") + "</span>" : "<small>—</small>") + "</td>"
        + '<td class="num hide-s">' + (c.pt ? (c.pt[0] ? c.pt[0] + " <small>(" + c.pt[1] + " succeeded)</small>" : "0") : "—") + "</td></tr>";
    });
    $("lg").innerHTML = h + "</tbody>";
  }

  /* ---------------- sectioned views: one screen per section instead of one long scroll ---------------- */
  function secBar(host, title, defs, cur, note) {
    host.innerHTML = '<span class="sec-t">' + title + "</span>" + defs.map(d => '<button class="chipbtn' + (d[0] === cur ? " on" : "") + '" data-sec="' + d[0] + '" title="' + esc(d[2] || "") + '">' + d[1] + "</button>").join("") + (note ? '<span class="sec-n">' + note + "</span>" : "");
  }
  /* draw an SVG to the exact pixel size of its host, so text never stretches */
  function chartIn(id, draw) { const el = $(id); if (!el) return; const r = el.getBoundingClientRect(); el.innerHTML = draw(Math.max(280, Math.floor(r.width)), Math.max(140, Math.floor(r.height))); }

  /* ---------------- the drift ---------------- */
  const DRS = [["world", "The world", "How many countries sit in each regime class, 1900 to now"], ["movers", "Movers", "Who is sliding and who is rising fastest"],
               ["signals", "Pressure signals", "Countries showing three or more observed strain conditions"], ["fallen", "Fallen by force", "Every government ended by force since 2020"]];
  function movers(k, n) {
    const xs = C.filter(c => delta(c, k) != null).sort((a, b) => delta(a, k) - delta(b, k));
    const max = Math.max(Math.abs(delta(xs[0], k)), delta(xs[xs.length - 1], k));
    const col = (list, cls) => '<div class="mv">' + list.map(c => { const d = delta(c, k); return '<button data-iso="' + c.id + '" title="' + esc(c.n) + '">' + esc(c.n) + '</button><div class="tr"><i style="width:' + Math.min(100, Math.abs(d) / max * 100).toFixed(0) + "%;background:" + DRIFT(0.5 + d / 0.5) + '"></i></div><span class="' + cls + '">' + K.signed(d) + "</span>"; }).join("") + "</div>";
    return '<div class="grid2 even"><div class="col"><h4 style="color:var(--down)">Sliding fastest</h4>' + col(xs.slice(0, n), "dn") + '</div><div class="col"><h4 style="color:var(--up)">Rising fastest</h4>' + col(xs.slice(-n).reverse(), "up") + "</div></div>";
  }
  function regimeChart(W, H) {
    /* stacked area: how many countries sat in each regime class, every year since 1900 */
    const L = 36, Rm = 10, T = 10, B = 22, n = LAST - Y0 + 1, pw = W - L - Rm, ph = H - T - B;
    const cnt = []; for (let i = 0; i < n; i++) { const a = [0, 0, 0, 0]; C.forEach(c => { if (c.hr && c.hr[i] !== "-") a[+c.hr[i]]++; }); cnt.push(a); }
    const max = Math.max.apply(null, cnt.map(a => a[0] + a[1] + a[2] + a[3])), x = i => L + i / (n - 1) * pw, y = v => T + ph - v / max * ph;
    let h = "";
    for (let v = 0; v <= max; v += 50) h += '<line class="gl" x1="' + L + '" x2="' + (W - Rm) + '" y1="' + y(v) + '" y2="' + y(v) + '"/><text x="' + (L - 6) + '" y="' + (y(v) + 3) + '" text-anchor="end">' + v + "</text>";
    let base = cnt.map(() => 0);
    [0, 1, 2, 3].forEach(k => {
      const top = cnt.map((a, i) => base[i] + a[k]);
      h += '<path fill="' + ROW[k][1] + '" fill-opacity=".88" d="' + K.path(top.map((v, i) => [x(i), y(v)])) + K.path(base.map((v, i) => [x(i), y(v)]).reverse()).replace("M", "L") + 'Z"/>';
      base = top;
    });
    for (let yr = 1900; yr <= LAST; yr += (W < 520 ? 40 : 20)) h += '<text x="' + x(yr - Y0) + '" y="' + (H - 6) + '" text-anchor="middle">' + yr + "</text>";
    [[1918, "1918"], [1945, "1945"], [1960, "decolonisation"], [1991, "1991"]].forEach(m => { h += '<line class="mk" x1="' + x(m[0] - Y0) + '" x2="' + x(m[0] - Y0) + '" y1="' + T + '" y2="' + (T + ph) + '"/><text class="mkt" x="' + (x(m[0] - Y0) + 4) + '" y="' + (T + 10) + '">' + m[1] + "</text>"; });
    return '<svg class="chart" viewBox="0 0 ' + W + " " + H + '" role="img" aria-label="Countries by regime type, 1900 to ' + LAST + '">' + h + "</svg>";
  }
  function drawDrift() {
    const pane = $("dr-pane");
    if (!built.dr) {
      built.dr = 1;
      $("v-drift").addEventListener("click", e => {
        const s = e.target.closest("[data-sec]"); if (s) { st.ds = s.dataset.sec; return sync(); }
        const mvb = e.target.closest("[data-mv]"); if (mvb) { st.mv = +mvb.dataset.mv; return drawDrift(); }
        const b = e.target.closest("[data-iso]"); if (b) pick(b.dataset.iso);
      });
    }
    secBar($("dr-secs"), "THE DRIFT", DRS, st.ds, "measured, not forecast · V-Dem to " + LAST);
    const room = Math.max(300, pane.clientHeight - 30);
    let h = "";
    if (st.ds === "world") {
      const n = [0, 0, 0, 0], pop = [0, 0, 0, 0]; let tot = 0;
      C.forEach(c => { if (c.row != null) { n[c.row]++; pop[c.row] += c.pop || 0; tot += c.pop || 0; } });
      const down = C.filter(c => c.d5 != null && c.d5 <= -0.05).length, up = C.filter(c => c.d5 != null && c.d5 >= 0.05).length;
      h = '<div class="tiles2">' + ROW.map((r, i) => '<div style="border-top-color:' + r[1] + '"><span>' + r[0] + "</span><b>" + n[i] + ' <small style="font:400 12px var(--mono);color:#8d96af">· ' + (pop[i] / tot * 100).toFixed(0) + "% of people</small></b><em>" + r[2] + "</em></div>").join("") + "</div>"
        + '<p class="lead">' + (n[0] + n[1]) + " autocracies to " + (n[2] + n[3]) + " democracies; about " + ((pop[0] + pop[1]) / tot * 100).toFixed(0) + "% of the world's people live under the former. Over five years <b class=\"dn\">" + down + '</b> countries fell by 0.05 or more on the liberal democracy index and <b class="up">' + up + "</b> rose by as much. Below: every year since " + Y0 + " — three waves of democracy (after 1918, after 1945, from the mid-1970s) and the ebb after each.</p>"
        + '<div class="chart-host" id="dr-chart"></div><div class="cleg" style="margin:0">' + ROW.map(r => '<span><i style="background:' + r[1] + '"></i>' + r[0] + "</span>").join("") + "</div>";
    } else if (st.ds === "movers") {
      h = '<p class="lead">Change in the liberal democracy index (0–1) over the last <span class="chips" style="display:inline-flex;vertical-align:middle">' + [1, 5, 10].map(k => '<button class="chipbtn' + (st.mv === k ? " on" : "") + '" data-mv="' + k + '">' + (k === 1 ? "year" : k + " years") + "</button>").join("") + "</span> Click a country to open it.</p>" + movers(st.mv, K.clamp(Math.floor((room - 70) / 21), 8, 24));
    } else if (st.ds === "signals") {
      const SH = { coup: "Coup attempt", force: "Forced change", erosion: "Erosion", violence: "Violence", polarised: "Polarised", military: "Military rule" };
      const hot = C.filter(c => c.sig && c.sig.length >= 3).sort((a, b) => b.sig.length - a.sig.length || (a.ldi || 0) - (b.ldi || 0));
      const tbl = list => '<table class="mx" style="width:100%"><thead><tr><th>Country</th>' + SIGK.map(s => '<th title="' + esc(SIG[s]) + '">' + SH[s] + "</th>").join("") + "</tr></thead><tbody>" + list.map(c => '<tr class="go" data-iso="' + c.id + '"><td><span class="fdot" style="background:' + ROW[c.row][1] + '" title="' + ROW[c.row][0] + '"></span>' + esc(c.n) + "</td>" + SIGK.map(s => '<td style="color:' + (c.sig.indexOf(s) >= 0 ? "#ff7a66" : "#232a3c") + '"><span class="dot"></span></td>').join("") + "</tr>").join("") + "</tbody></table>";
      const half = Math.ceil(hot.length / 2);
      h = '<p class="lead">Six observed conditions that students of coups and breakdowns watch; the ' + hot.length + " countries showing three or more. A count of what has already been recorded — not a probability, and not a prediction that any government will fall.</p>"
        + '<div class="grid2 even"><div class="col scroll">' + tbl(hot.slice(0, half)) + '</div><div class="col scroll">' + tbl(hot.slice(half)) + "</div></div>"
        + '<p class="wr-note" style="max-width:none">Coup attempt: within ten years (Powell &amp; Thyne, to ' + R.meta.ptLast + "). Forced change: a regime ended by force within ten years (V-Dem). Erosion: liberal democracy index down 0.10+ since " + (LAST - 5) + ". Violence, polarised: V-Dem expert scores of 2.5+ and 3.0+ on 0–4 scales. Military rule: V-Dem's military dimension of the executive at 0.5+.</p>";
    } else {
      const rec = R.recent.filter(e => e[1] >= 2020).concat(NT.after || []).sort((a, b) => b[1] - a[1] || b[2] - a[2] || b[3] - a[3]);
      h = '<p class="lead">Every regime recorded as ending by coup, self-coup, uprising, civil war or intervention since 2020, newest first, with what replaced it. The full record back to 1789 is in the Coups.</p>'
        + '<div class="col scroll" style="flex:1"><table class="tbl"><thead><tr><th>Date</th><th>Country</th><th>How</th><th>What fell</th><th>What followed</th></tr></thead><tbody>'
        + rec.map(e => { const c = BY[e[0]]; return '<tr class="go" data-iso="' + e[0] + '"><td class="yr">' + e[3] + " " + K.MON[e[2] - 1] + " " + e[1] + '</td><td style="color:var(--paper);font-family:var(--display);white-space:nowrap">' + esc(c ? c.n : e[0]) + '</td><td><span class="tag ' + (e[4] === 8 ? "ok" : e[4] === 2 ? "br" : "no") + '" style="margin:0">' + ENDT[e[4]] + "</span></td><td>" + esc(e[6]) + "</td><td>" + esc(e[7] || "—") + "</td></tr>"; }).join("")
        + '</tbody></table></div><p class="wr-note" style="max-width:none">' + esc(NT.afterNote || "") + ' <a href="coups.html">Open the Coups ⟶</a></p>';
    }
    pane.innerHTML = h; pane.scrollTop = 0;
    if (st.ds === "world") chartIn("dr-chart", regimeChart);
  }

  /* ---------------- the United States ---------------- */
  const USS = [["now", "Standing", "The two indices, the long line since 1900, and what moved"], ["time", "Timeline", "A generation of run-up, then 2025–26 event by event"],
               ["disputes", "Disputes", "Eight live disputes, each side in its own terms"], ["bills", "Legislation", "The measures that matter and where they stand"],
               ["read", "Five readings", "Rival readings of where the country is heading"], ["ahead", "Common ground & signposts", "What all readings accept, and the dated tests ahead"]];
  /* one list for the timeline: the run-up (year only) and the dated events */
  const EV = U.arc.map(a => ({ t: a[0] + 0.5, lab: String(a[0]), k: a[1], n: a[2], x: a[3], u: a[4] }))
    .concat(U.tl.map(a => { const p = a[0].split("-").map(Number); return { t: p[0] + (p[1] - 1) / 12 + (p[2] - 1) / 365, lab: p[2] + " " + K.MON[p[1] - 1] + " " + p[0], k: a[1], n: a[2], x: a[3], u: a[4] }; }));
  function usChart(W, H) {
    const L = 34, Rm = 12, T = 10, B = 20, s = R.usa, n = s.ldi.length, pw = W - L - Rm, ph = H - T - B, lo = 0.2;
    const x = i => L + i / (n - 1) * pw, y = v => T + ph - (v - lo) / (1 - lo) * ph;
    let h = "";
    for (let v = lo; v <= 1.001; v += 0.2) h += '<line class="gl" x1="' + L + '" x2="' + (W - Rm) + '" y1="' + y(v) + '" y2="' + y(v) + '"/><text x="' + (L - 6) + '" y="' + (y(v) + 3) + '" text-anchor="end">' + v.toFixed(1) + "</text>";
    for (let yr = 1900; yr <= LAST; yr += (W < 520 ? 40 : 20)) h += '<text x="' + x(yr - s.y0) + '" y="' + (H - 5) + '" text-anchor="middle">' + yr + "</text>";
    [[1920, "women's suffrage"], [1965, "Voting Rights Act"], [2001, "9/11"], [2017, "2017"]].forEach(m => { h += '<line class="mk" x1="' + x(m[0] - s.y0) + '" x2="' + x(m[0] - s.y0) + '" y1="' + T + '" y2="' + (T + ph) + '"/><text class="mkt" x="' + (x(m[0] - s.y0) - 4) + '" y="' + (T + ph - 6) + '" text-anchor="end">' + m[1] + "</text>"; });
    const line = (arr, col, wd) => '<path fill="none" stroke="' + col + '" stroke-width="' + wd + '" d="' + K.path(arr.map((v, i) => [x(i), y(v)])) + '"/>';
    h += line(s.edi, "#5b93b8", 1.6) + line(s.ldi, "#e8c455", 2.2);
    const e = n - 1;
    h += '<circle cx="' + x(e) + '" cy="' + y(s.ldi[e]) + '" r="4" fill="#e8c455"/><text class="lab" x="' + (x(e) - 8) + '" y="' + (y(s.ldi[e]) + 15) + '" text-anchor="end">' + LAST + ": " + s.ldi[e].toFixed(2) + "</text>";
    return '<svg class="chart" viewBox="0 0 ' + W + " " + H + '" role="img" aria-label="United States democracy indices, 1900 to ' + LAST + '">' + h + "</svg>";
  }
  /* the timeline strip: one lane per kind of event; the axis is broken so that 2000–2024 takes a
     quarter of the width and the two crowded years take the rest */
  function usStrip(W, H) {
    const small = W < 640, L = small ? 10 : 150, Rm = 14, T = 8, B = 24, pw = W - L - Rm, ph = H - T - B, kinds = Object.keys(U.kinds), lh = ph / kinds.length;
    const split = 0.24, gap = 0.035, x = t => t < 2025 ? L + (t - 2000) / 25 * split * pw : L + (split + gap) * pw + (t - 2025) / 1.95 * (1 - split - gap) * pw;
    let h = '<rect x="' + L + '" y="' + T + '" width="' + (split * pw) + '" height="' + ph + '" fill="rgba(255,255,255,.02)"/><rect x="' + x(2025) + '" y="' + T + '" width="' + ((1 - split - gap) * pw) + '" height="' + ph + '" fill="rgba(255,255,255,.035)"/>';
    kinds.forEach((k, i) => {
      const yy = T + lh * i;
      h += '<line class="gl" x1="' + L + '" x2="' + (W - Rm) + '" y1="' + (yy + lh / 2) + '" y2="' + (yy + lh / 2) + '" style="stroke:' + U.kinds[k][1] + ';opacity:.16"/>';
      if (!small) h += '<text class="lane-t' + (st.tk === k ? " on" : "") + '" data-tk="' + k + '" x="' + (L - 12) + '" y="' + (yy + lh / 2 + 4) + '" text-anchor="end">' + U.kinds[k][0] + "</text>";
    });
    for (let yr = 2000; yr < 2025; yr += 5) h += '<text x="' + x(yr) + '" y="' + (H - 7) + '" text-anchor="middle">' + yr + "</text>";
    for (let m = 0; m < 24; m++) { const t = 2025 + m / 12; h += '<line class="gl" x1="' + x(t) + '" x2="' + x(t) + '" y1="' + T + '" y2="' + (T + ph) + '"' + (m === 12 ? ' style="stroke:rgba(232,196,85,.4)"' : "") + "/>"; if (m % (small ? 6 : 2) === 0) h += '<text x="' + (x(t) + 3) + '" y="' + (H - 7) + '">' + K.MON[m % 12] + (m % 12 === 0 ? " " + (2025 + m / 12) : "") + "</text>"; }
    const lastX = {};
    EV.forEach((e, i) => {
      const li = kinds.indexOf(e.k), px = x(e.t); let py = T + lh * li + lh / 2;
      if (lastX[e.k] != null && px - lastX[e.k].x < 13) { py += lastX[e.k].up ? -6 : 6; lastX[e.k] = { x: px, up: !lastX[e.k].up }; } else lastX[e.k] = { x: px, up: true };
      h += '<circle class="ev-d' + (i === st.te ? " sel" : "") + (st.tk && st.tk !== e.k ? " dim" : "") + '" data-te="' + i + '" cx="' + px.toFixed(1) + '" cy="' + py.toFixed(1) + '" r="' + (i === st.te ? 7.5 : 5.5) + '" fill="' + U.kinds[e.k][1] + '"><title>' + esc(e.lab + " — " + e.n) + "</title></circle>";
    });
    return '<svg class="chart" viewBox="0 0 ' + W + " " + H + '" role="img" aria-label="Timeline of United States events by kind">' + h + "</svg>";
  }
  function usStep(d) {
    const ok = i => !st.tk || EV[i].k === st.tk; let i = st.te;
    do { i += d; } while (i >= 0 && i < EV.length && !ok(i));
    if (i >= 0 && i < EV.length) { st.te = i; drawUSA(); }
  }
  function drawUSA() {
    const pane = $("us-pane"), us = BY.USA;
    if (!built.us) {
      built.us = 1; st.te = EV.length - 2;
      $("v-usa").addEventListener("click", e => {
        const s = e.target.closest("[data-sec]"); if (s) { st.us = s.dataset.sec; return sync(); }
        const tk = e.target.closest("[data-tk]"); if (tk) { st.tk = st.tk === tk.dataset.tk ? null : tk.dataset.tk; if (st.tk && EV[st.te].k !== st.tk) { const j = EV.map((x, i) => x.k === st.tk ? i : -1).filter(i => i >= 0).pop(); if (j != null) st.te = j; } return drawUSA(); }
        const te = e.target.closest("[data-te]"); if (te) { st.te = +te.dataset.te; return drawUSA(); }
        const sp = e.target.closest("[data-step]"); if (sp) return usStep(+sp.dataset.step);
        const d = e.target.closest("[data-ud]"); if (d) { st.ud = +d.dataset.ud; return drawUSA(); }
        const r = e.target.closest("[data-ur]"); if (r) { st.ur = +r.dataset.ur; return drawUSA(); }
      });
    }
    secBar($("us-secs"), "THE UNITED STATES", USS, st.us, "read " + esc(U.asOf));
    let h = "";
    if (st.us === "now") {
      const peak = Math.max.apply(null, R.usa.ldi), py = R.usa.y0 + R.usa.ldi.indexOf(peak), sm = '<small style="font:400 12px var(--mono);color:#7d87a1">';
      h = '<div class="grid2"><div class="col">'
        + '<p class="lead">The world\'s oldest constitutional republic, measured by the same two instruments as every other country. Both describe calendar ' + LAST + "; neither yet reflects the midterm elections of November 2026.</p>"
        + '<div class="tiles2" style="grid-template-columns:1fr 1fr"><div><span>Freedom House 2026</span><b>' + us.fh[0] + sm + " /100</small></b><em>Free. Down three points in a year — the sharpest fall among Free countries — and twelve over two decades.</em></div>"
        + "<div><span>V-Dem liberal democracy " + LAST + "</span><b>" + K.fmt(us.ldi) + "</b><em>From " + K.fmt(R.usa.ldi[R.usa.ldi.length - 2]) + " in " + (LAST - 1) + "; peak " + K.fmt(peak) + " in " + py + ". Rank " + (ranked.indexOf(us) + 1) + " of " + ranked.length + ".</em></div>"
        + '<div><span>V-Dem regime class</span><b style="font-size:19px">' + ROW[us.row][0] + "</b><em>Re-classed from liberal democracy for " + LAST + ", a status held for some fifty years.</em></div>"
        + "<div><span>Polarisation</span><b>" + K.fmt(us.pol, 1) + sm + " /4</small></b><em>Society split into hostile camps — among the highest scores in the world.</em></div></div>"
        + '<div class="callout"><b style="color:var(--gold-bright)">How to read these numbers — and the case against them.</b> Both indices are built from the judgments of country experts, not counts of events. Defenders note that the two organisations work independently and agree, that the scores fell under presidents of both parties, and that one method is applied to every country. Critics answer that academics and NGO staff lean one way politically, that a one-year fall this steep reflects alarm as much as measurement, and that what can be counted — elections held on time, incumbents losing, courts obeyed — moved far less in 2025–26 than the scores did. The archive reports the numbers and the objection, and takes neither as settled.</div>'
        + '</div><div class="col"><h4>The long line, 1900–' + LAST + '<small>the climb is the widening of the vote: women in 1920, Black southerners in fact only after 1965</small></h4><div class="chart-host" id="us-chart"></div>'
        + '<div class="cleg" style="margin:0"><span><i style="background:#e8c455"></i>Liberal democracy index</span><span><i style="background:#5b93b8"></i>Electoral democracy index</span></div>'
        + '<h4>What moved<small>V-Dem components; the largest change is the legislature\'s hold on the executive</small></h4><div class="mx-wrap" style="padding:0"><table class="parts"><thead><tr><th>Component</th><th>2015</th><th>2020</th><th>2023</th><th>2024</th><th>' + LAST + "</th><th>2023 → " + LAST + "</th></tr></thead><tbody>"
        + R.usa.parts.map((p, i) => { const d = p[6] - p[4], bad = i >= 7 ? d > 0 : d < 0, dp = p[2] > 1.5 ? 1 : 2; return "<tr><td>" + esc(p[0]) + "</td>" + [2, 3, 4, 5, 6].map(k => "<td>" + K.fmt(p[k], dp) + "</td>").join("") + '<td class="chg ' + (Math.abs(d) < 0.02 ? "" : bad ? "dn" : "up") + '">' + K.signed(d, dp) + "</td></tr>"; }).join("")
        + "</tbody></table></div></div></div>";
    } else if (st.us === "time") {
      const e = EV[st.te], shown = EV.filter(x => !st.tk || x.k === st.tk), pos = shown.indexOf(e) + 1;
      h = '<p class="lead">Each dot is an event; each row a kind of event. The left quarter is the run-up since 2000 — the quarrels over presidential power, the courts and the rules of elections were a generation in the making, under both parties — and the rest is 2025–26 month by month. Click a dot, or step with ← →. Click a row name to follow one thread.</p>'
        + '<div class="chart-host" id="us-strip" style="min-height:230px"></div>'
        + '<div class="tl-card"><button class="step" data-step="-1" title="Earlier (←)" aria-label="Earlier">◂</button><div><div class="sd-d" style="margin-bottom:4px">' + esc(e.lab) + ' · <span class="fdot" style="background:' + U.kinds[e.k][1] + '"></span>' + U.kinds[e.k][0] + " · " + pos + " of " + shown.length + (st.tk ? ' <button class="chipbtn" data-tk="' + st.tk + '" style="margin-left:8px">show all kinds</button>' : "") + '</div><div class="sd-t">' + esc(e.n) + '</div><p class="sd-p">' + esc(e.x) + '</p><div class="sd-links" style="margin-top:8px">' + K.link(src(e.u), "Source: " + K.host(src(e.u))) + '</div></div><button class="step" data-step="1" title="Later (→)" aria-label="Later">▸</button></div>';
    } else if (st.us === "disputes") {
      const t = U.topics[st.ud], ab = t.ab || ["The administration and its supporters", "Its critics"];
      h = '<div class="grid2 md"><div class="mlist">' + U.topics.map((x, i) => '<button data-ud="' + i + '"' + (i === st.ud ? ' class="on"' : "") + ">" + esc(x.n) + "</button>").join("") + "</div>"
        + '<div class="col"><p class="lead">Where it stands, then the strongest form of each side\'s case in its own terms.</p><article class="rec"><header><b>' + esc(t.n) + '</b></header><div class="st">' + esc(t.st) + '</div><div class="cols"><div class="pro"><div class="mf-k" style="color:var(--gold)">' + ab[0] + "</div>" + esc(t.a) + '</div><div class="con"><div class="mf-k" style="color:#9fb4d8">' + ab[1] + "</div>" + esc(t.b) + "</div></div><footer>" + srcLinks(t.u) + "</footer></article></div></div>";
    } else if (st.us === "bills") {
      h = '<p class="lead">The measures behind the disputes and where each stood when read. From January 2027 a Democratic Congress faces a Republican president: expect vetoes, and few new laws.</p><table class="tbl"><thead><tr><th>Measure</th><th>Status</th><th>What it does</th></tr></thead><tbody>' + U.bills.map(b => '<tr><td class="m" style="width:24%"><b style="font-family:var(--display)">' + esc(b[0]) + '</b></td><td class="yr" style="white-space:normal;width:26%">' + esc(b[1]) + "</td><td>" + esc(b[2]) + ' <span class="srcs">' + K.link(src(b[3]), "source") + "</span></td></tr>").join("") + "</tbody></table>";
    } else if (st.us === "read") {
      const t = U.theses[st.ur];
      h = '<p class="lead">Serious observers disagree about the direction of the country, and that disagreement is itself the most important fact. Each reading is given with the evidence its holders cite, the evidence against it, and what would tell you it is right. None is the archive\'s own.</p>'
        + '<div class="picks">' + U.theses.map((x, i) => '<button data-ur="' + i + '"' + (i === st.ur ? ' class="on"' : "") + "><b>" + (i + 1) + ". " + esc(x.n) + "</b><small>" + esc(x.who) + "</small>" + esc(x.claim) + "</button>").join("") + "</div>"
        + '<article class="rec"><div class="cols c3"><div class="pro"><div class="mf-k">Evidence cited for</div><ul>' + t.pro.map(x => "<li>" + esc(x) + "</li>").join("") + '</ul></div><div class="con"><div class="mf-k">Evidence cited against</div><ul>' + t.con.map(x => "<li>" + esc(x) + "</li>").join("") + '</ul></div><div><div class="mf-k" style="color:var(--gold)">Watch for</div><ul>' + t.watch.map(x => "<li>" + esc(x) + "</li>").join("") + "</ul></div></div><footer>" + srcLinks(t.u) + "</footer></article>";
    } else {
      h = '<div class="grid2 even"><div class="col"><h4>What the readings share<small>the nearest thing to settled ground</small></h4><ol class="olist">' + U.shared.map(x => "<li>" + esc(x) + "</li>").join("") + "</ol></div>"
        + '<div class="col"><h4>Signposts<small>dated tests that will favour one reading over another</small></h4><dl class="sp">' + U.signposts.map(x => "<dt>" + esc(x[0]) + "</dt><dd>" + esc(x[1]) + "</dd>").join("") + "</dl></div></div>"
        + '<h4>Sources</h4><p class="srcs">' + Object.keys(U.src).map(k => K.link(U.src[k][1], U.src[k][0])).join("") + '</p><p class="wr-note" style="max-width:none">Events after ' + esc(U.asOf) + " are not included; election figures were still being counted when read.</p>";
    }
    pane.innerHTML = h; pane.scrollTop = 0;
    if (st.us === "now") chartIn("us-chart", usChart); else if (st.us === "time") chartIn("us-strip", usStrip);
  }

  /* ---------------- the side panel ---------------- */
  function spark(c) {
    const W = 330, H = 74, n = c.hl.length, x = i => 2 + i / (n - 1) * (W - 4), y = v => 4 + (1 - v) * 48;
    let segs = [], cur = [];
    c.hl.forEach((v, i) => { if (v < 0) { if (cur.length) segs.push(cur); cur = []; } else cur.push([x(i), y(v / 100)]); }); if (cur.length) segs.push(cur);
    let h = '<line class="ax" x1="2" x2="' + (W - 2) + '" y1="52" y2="52"/>';
    segs.forEach(s => { h += '<path class="ar" d="' + K.path(s) + "L" + s[s.length - 1][0].toFixed(1) + " 52L" + s[0][0].toFixed(1) + ' 52Z"/><path class="ln" d="' + K.path(s) + '"/>'; });
    /* the regime class of each year as a strip under the line */
    const w = (W - 4) / n; for (let i = 0; i < n; i++) if (c.hr[i] !== "-") h += '<rect x="' + (2 + i * w).toFixed(1) + '" y="55" width="' + (w + .4).toFixed(1) + '" height="5" fill="' + ROW[+c.hr[i]][1] + '"/>';
    [1900, 1950, 2000].forEach(yr => { h += '<text x="' + x(yr - Y0) + '" y="71">' + yr + "</text>"; }); h += '<text x="' + (W - 2) + '" y="71" text-anchor="end">' + LAST + "</text>";
    return '<svg class="spark" viewBox="0 0 ' + W + " " + H + '" preserveAspectRatio="none" role="img" aria-label="Liberal democracy index since 1900">' + h + "</svg>";
  }
  const meter = (label, v, max, col) => "<span>" + label + '</span><div class="tr"><i style="width:' + (v == null ? 0 : K.clamp(v / max * 100, 0, 100)).toFixed(0) + "%" + (col ? ";background:" + col : "") + '"></i></div><span class="v">' + (v == null ? "—" : K.fmt(v, max > 1 ? 1 : 2)) + "</span>";
  function card(c) {
    const f = NT.forms[formOf(c)], note = NT.note[c.id];
    let h = '<button class="sd-x" title="Close (Esc)" aria-label="Close">×</button><div class="sd-k">' + esc(c.rg || (formOf(c) === "TE" ? "Territory" : "Small state")) + '</div><div class="sd-t">' + esc(c.n) + '</div><div class="sd-d">' + esc(f ? f[0] : "") + (c.pop ? " · " + K.pop(c.pop) + " people" : "") + "</div>";
    h += '<div class="cc-big">' + (c.fh ? '<div><span class="k">Freedom House 2026</span><b>' + c.fh[0] + '<small> /100</small></b><span class="pill ' + c.fh[1] + '">' + FHS[c.fh[1]][0] + "</span><em>Political rights " + c.fh[2] + "/40 · civil liberties " + c.fh[3] + "/60</em></div>" : "")
      + (c.ldi != null ? '<div><span class="k">V-Dem ' + LAST + "</span><b>" + K.fmt(c.ldi) + '</b><span class="pill" style="color:' + ROW[c.row][1] + ";border-color:" + ROW[c.row][1] + '">' + ROW[c.row][0] + "</span><em>Liberal democracy, 0–1 · rank " + (ranked.indexOf(c) + 1) + " of " + ranked.length + "</em></div>" : "") + "</div>";
    if (f) h += '<p class="hint" style="margin-top:6px">' + esc(f[0]) + ": " + esc(f[1].charAt(0).toLowerCase() + f[1].slice(1)) + "</p>";
    if (note) h += '<div class="sd-k">In brief</div><p class="sd-p">' + esc(note.t) + "</p>" + (note.d ? '<div class="sd-links"><a href="doctrines.html#v=compass&i=' + note.d + '">The doctrine, in the Doctrines ⟶</a></div>' : "") + (c.id === "USA" ? '<div class="sd-links"><a href="#v=usa" data-go="usa">The United States in detail ⟶</a></div>' : "");
    if (c.fhOnly) return h + '<p class="hint">V-Dem does not cover this state, so only the Freedom House score is shown.</p>';
    h += '<div class="sd-k">Liberal democracy since 1900</div>' + spark(c) + '<dl class="kv" style="margin-top:6px"><dt>1 year</dt><dd class="mono ' + (c.d1 < -0.02 ? "dn" : c.d1 > 0.02 ? "up" : "") + '">' + K.signed(c.d1) + '</dd><dt>5 years</dt><dd class="mono ' + (c.d5 < -0.02 ? "dn" : c.d5 > 0.02 ? "up" : "") + '">' + K.signed(c.d5) + '</dd><dt>10 years</dt><dd class="mono ' + (c.d10 < -0.02 ? "dn" : c.d10 > 0.02 ? "up" : "") + '">' + K.signed(c.d10) + "</dd></dl>";
    h += '<div class="sd-k">What the score is made of</div><div class="meter">' + meter("Clean elections", c.edi, 1) + meter("Civil liberties", c.civ, 1) + meter("Free expression", c.fx, 1) + meter("Rule of law", c.rule, 1) + meter("Courts constrain the executive", c.jud, 1) + meter("Legislature constrains it", c.leg, 1) + meter("Civil society", c.cs, 1) + meter("Corruption", c.corr, 1, "#ff7a66") + "</div>";
    if (c.ideo) {
      h += '<div class="sd-k">In whose name it rules</div><p class="sd-p" style="font-size:12.5px">' + (c.ideo[0] < 2 ? "The government makes no strong ideological claim" : "The government promotes an ideology that experts class as <b style=\"color:var(--paper)\">" + esc(c.ideo[1].split("").map(k => IDEO[k][0].toLowerCase()).join(", ") || "of no listed type") + "</b>") + ".</p>"
        + '<div class="meter" style="margin-top:6px">' + meter("An ideology", c.ideo[0], 4) + meter("The leader's person", c.lead, 4) + meter("Performance: growth, order", c.perf, 4) + meter("Law and procedure", c.law, 4) + '</div><p class="hint">V-Dem expert scores, 0–4, for how far each claim is used to justify rule (' + c.ideoY + ").</p>";
    }
    h += '<div class="sd-k">The economy</div><div class="meter">' + meter("Private ownership of capital", c.own, 4) + meter("Property rights", c.prop, 1) + "</div>";
    h += '<div class="sd-k">Pressure signals · ' + c.sig.length + " of 6</div>" + SIGK.map(s => '<div class="sg-row' + (c.sig.indexOf(s) >= 0 ? " on" : "") + '"><i></i>' + SIG[s] + "</div>").join("") + '<p class="hint">Observed conditions, not a forecast. Polarisation ' + K.fmt(c.pol, 1) + " and political violence " + K.fmt(c.viol, 1) + " on 0–4 scales.</p>";
    h += '<div class="sd-k">Coups and overthrows</div><p class="sd-p" style="font-size:12.5px">' + (c.pt[0] ? c.pt[0] + " coup attempt" + (c.pt[0] > 1 ? "s" : "") + " since 1950, " + c.pt[1] + " successful" + (c.pt[2] ? " — the last in " + c.pt[2] : "") + "." : "No coup attempt recorded since 1950.") + (c.lf ? " The last government to end by force: " + esc(c.lf[2]) + ", " + c.lf[0] + " (" + ENDT[c.lf[1]].toLowerCase() + ")." : "") + "</p>";
    h += '<div class="sd-links"><a href="coups.html#v=record&c=' + c.id + '">Its record in the Coups ⟶</a>' + K.link("https://freedomhouse.org/country/scores", "Freedom House") + K.link("https://www.v-dem.net/", "V-Dem") + "</div>";
    return h;
  }
  const INTRO = {
    map: ["THE MAP", "Every country coloured by one measure at a time. Start with the Freedom House score; switch to regime type or liberal democracy and drag the year back to watch the century. Click a country to open it."],
    compass: ["THE COMPASS OF NATIONS", "The Doctrines chart places ideas; this one places states. Across: who owns the economy and how safe property is. Down: how free politics are. Most of the world sits on a diagonal — but not all of it: note the market economies near the top."],
    ledger: ["THE LEDGER", "All " + C.length + " countries and territories in one table. Sort by any column; filter by region or status."],
    drift: ["THE DRIFT", "Direction rather than position: who has moved, where strain is showing, and where governments have fallen by force. Four sections, one screen each — step with ← →."]
  };
  function renderSide() {
    const side = $("dc-side"), c = st.c && BY[st.c];
    if (st.v === "usa" || (!c && innerWidth <= 860)) { side.hidden = true; return; }
    side.hidden = false;
    if (c) { side.innerHTML = '<div class="dc-card">' + card(c) + "</div>"; side.scrollTop = 0; return; }
    const t = INTRO[st.v];
    side.innerHTML = '<div class="dc-card intro"><div class="sd-k">' + t[0] + '</div><p>' + t[1] + "</p>"
      + '<div class="q" style="border-color:#49c9b8"><b style="color:#49c9b8">Freedom House</b><span>Scores political rights (0–40) and civil liberties (0–60) for ' + C.filter(x => x.fh).length + " countries and territories. This is the 2026 edition, describing 2025.</span></div>"
      + '<div class="q" style="border-color:#e8c455"><b style="color:#e8c455">V-Dem</b><span>Several thousand country experts code hundreds of indicators back to 1789; ' + C.filter(x => x.ldi != null).length + " countries are covered. Regime type, the components, ideology and drift all come from it.</span></div>"
      + '<div class="q" style="border-color:#9a7fd1"><b style="color:#9a7fd1">The archive\'s notes</b><span>Form of government and the short briefs are hand-written; they are marked as such.</span></div>'
      + '<p style="margin-top:12px">These are measurements made by people, and people argue with them. Where two independent scorers agree, the picture is probably sound; where a score surprises you, open the country and look at what it is made of.</p>'
      + '<div class="sd-k">Start with</div>' + ["USA", "CHN", "IND", "RUS", "IRN", "HUN", "BFA", "SYR"].map(i => '<button class="nchip" data-iso="' + i + '">' + esc(BY[i].n) + "</button>").join("") + "</div>";
  }

  /* ---------------- boot ---------------- */
  function applyHash() {
    if (location.hash === K.hash.self && built.boot) return;
    const q = K.hash.read();
    if (q.v && tabs.ids.indexOf(q.v) >= 0) st.v = q.v;
    if (q.s && st.v === "usa" && USS.some(x => x[0] === q.s)) st.us = q.s;
    if (q.s && st.v === "drift" && DRS.some(x => x[0] === q.s)) st.ds = q.s;
    if (q.m && MODES[q.m]) st.m = q.m;
    if (q.y && +q.y >= Y0 && +q.y <= LAST) st.y = +q.y;
    st.c = q.c && BY[q.c] ? q.c : null;
    built.boot = 1; sync(true);
    if (st.c && st.v === "map") setTimeout(() => map.focus(st.c), 60);
  }
  function boot() {
    tabs = K.tabs(() => st.v, go);
    $("dc-side").addEventListener("click", e => {
      if (e.target.closest(".sd-x")) return pick(null);
      const g = e.target.closest("[data-go]"); if (g) { e.preventDefault(); st.c = null; return go(g.dataset.go); }
      const b = e.target.closest("[data-iso]"); if (b) pick(b.dataset.iso);
    });
    document.addEventListener("keydown", e => {
      if (e.target.closest("input, textarea") || e.ctrlKey || e.metaKey || e.altKey) return;
      if (e.key === "Escape" && st.c) return pick(null);
      const d = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0; if (!d) return;
      if (st.v === "usa" && st.us === "time") return usStep(d);           /* ← → walk the timeline … */
      const secs = st.v === "usa" ? USS : st.v === "drift" ? DRS : null;  /* … or step between sections */
      if (secs) { const k = st.v === "usa" ? "us" : "ds", i = secs.findIndex(x => x[0] === st[k]) + d; if (secs[i]) { st[k] = secs[i][0]; sync(); } }
    });
    let rt = 0; window.addEventListener("resize", () => { clearTimeout(rt); rt = setTimeout(() => { if (st.v === "usa" || st.v === "drift") render(st.v); renderSide(); }, 140); });
    K.finder($("dc-q"), q => C.filter(c => c.n.toLowerCase().indexOf(q) >= 0 || c.id.toLowerCase() === q).sort((a, b) => (a.n.toLowerCase().indexOf(q) - b.n.toLowerCase().indexOf(q)) || (b.pop || 0) - (a.pop || 0))
      .map(c => ({ label: c.n, sub: c.fh ? "FH " + c.fh[0] + " · " + FHS[c.fh[1]][0] : "", id: c.id })), h => pick(h.id));
    window.addEventListener("hashchange", applyHash);
    applyHash();
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot); else boot();
})();
